import sys
from collections import Counter

def parse_molecule(molecule):
    i = 0
    result = []
    while i < len(molecule):
        atom = molecule[i]
        if i + 1 < len(molecule) and molecule[i+1].isdigit():
            count = int(molecule[i+1:])
            result.append((atom, count))
            i += 1 + len(str(count))
        else:
            result.append((atom, 1))
            i += 1
    return result

def get_atom_counts(molecule):
    return Counter(atom for atom, count in parse_molecule(molecule))

def max_output(input_molecule, num_input_molecules, output_molecule):
    input_counts = get_atom_counts(input_molecule)
    output_counts = get_atom_counts(output_molecule)

    min_count = float('inf')
    for atom, count in output_counts.items():
        if atom not in input_counts:
            return 0
        min_count = min(min_count, input_counts[atom] // count)

    return min_count * num_input_molecules

if __name__ == "__main__":
    input_data = sys.stdin.read().splitlines()
    input_molecule = input_data[0].split()[0]
    num_input_molecules = int(input_data[0].split()[1])
    output_molecule = input_data[1]

    result = max_output(input_molecule, num_input_molecules, output_molecule)
    print(result)
